package main

import (
	"fmt"
	"runtime"
	"strconv"
	"strings"
)

// Flags holds all command-line options.
type Flags struct {
	// strings
	CfgFile          string
	LogFile          string
	InputFile        string
	OutputFile       string
	IgnoreFromFile   string
	DbPath           string
	Style            string
	Since            string
	Until            string
	MaxAge           string
	MinAge           string
	Storage          string

	// string slices
	IgnoreDirs         []string
	IgnoreDirsPattern  []string
	TypeFilter         []string
	ExcludeTypeFilter  []string

	// ints
	MaxCores int
	Top      int
	Depth    int

	// bools
	SequentialScanning bool
	ShowDisks          bool
	ShowApparentSize   bool
	ShowRelativeSize   bool
	ShowAnnexedSize    bool
	ShowVersion        bool
	ShowHelp           bool
	ShowItemCount      bool
	ShowMTime          bool
	NoColor            bool
	Mouse              bool
	NonInteractive     bool
	NoProgress         bool
	NoUnicode          bool
	NoCross            bool
	NoHidden           bool
	NoDelete           bool
	NoSpawnShell       bool
	FollowSymlinks     bool
	Profiling          bool
	ReadFromStorage    bool
	Summarize          bool
	UseSIPrefix        bool
	NoPrefix           bool
	ShowInKiB          bool
	WriteConfig        bool
	ReverseSort        bool
	ArchiveBrowsing    bool
	CollapsePath       bool
	UseGitIgnore       bool

	// positional
	Args []string
}

func defaultFlags() *Flags {
	return &Flags{
		LogFile:    "/dev/null",
		MaxCores:   runtime.NumCPU(),
		IgnoreDirs: []string{"/proc", "/dev", "/sys", "/run"},
		Storage:    "memory",
	}
}

// flagDef represents a known CLI flag.
type flagDef struct {
	Short   string
	Long    string
	Has     string // "bool", "string", "strings", "int"
}

// flag registry drives parsing (NOT help formatting).
var flagDefs = []flagDef{
	{"", "archive-browsing", "bool"},
	{"", "collapse-path", "bool"},
	{"", "config-file", "string"},
	{"D", "db", "string"},
	{"", "depth", "int"},
	{"", "enable-profiling", "bool"},
	{"E", "exclude-type", "strings"},
	{"L", "follow-symlinks", "bool"},
	{"h", "help", "bool"},
	{"i", "ignore-dirs", "strings"},
	{"I", "ignore-dirs-pattern", "strings"},
	{"X", "ignore-from", "string"},
	{"f", "input-file", "string"},
	{"l", "log-file", "string"},
	{"", "max-age", "string"},
	{"m", "max-cores", "int"},
	{"", "min-age", "string"},
	{"", "mouse", "bool"},
	{"c", "no-color", "bool"},
	{"x", "no-cross", "bool"},
	{"", "no-delete", "bool"},
	{"H", "no-hidden", "bool"},
	{"", "no-prefix", "bool"},
	{"p", "no-progress", "bool"},
	{"", "no-spawn-shell", "bool"},
	{"u", "no-unicode", "bool"},
	{"n", "non-interactive", "bool"},
	{"o", "output-file", "string"},
	{"r", "read-from-storage", "bool"},
	{"", "reverse-sort", "bool"},
	{"", "sequential", "bool"},
	{"A", "show-annexed-size", "bool"},
	{"a", "show-apparent-size", "bool"},
	{"d", "show-disks", "bool"},
	{"k", "show-in-kib", "bool"},
	{"C", "show-item-count", "bool"},
	{"M", "show-mtime", "bool"},
	{"B", "show-relative-size", "bool"},
	{"S", "shared", "bool"},
	{"s", "summarize", "bool"},
	{"", "si", "bool"},
	{"", "since", "string"},
	{"", "storage", "string"},
	{"", "style", "string"},
	{"t", "top", "int"},
	{"T", "type", "strings"},
	{"", "until", "string"},
	{"g", "use-git-ignore", "bool"},
	{"v", "version", "bool"},
	{"w", "write-config", "bool"},
}

func findFlagByLong(long string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].Long == long {
			return &flagDefs[i]
		}
	}
	return nil
}

func findFlagByShort(short string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].Short == short {
			return &flagDefs[i]
		}
	}
	return nil
}

// setFlagValue updates the Flags struct based on long name.
func setFlagValue(f *Flags, long string, value string, hasValue bool) error {
	def := findFlagByLong(long)
	if def == nil {
		return fmt.Errorf("unknown flag: --%s", long)
	}
	switch def.Has {
	case "bool":
		if hasValue {
			b, err := strconv.ParseBool(value)
			if err != nil {
				return fmt.Errorf("invalid argument %q for %q flag", value, "--"+long)
			}
			assignBool(f, long, b)
		} else {
			assignBool(f, long, true)
		}
	case "string":
		if !hasValue {
			return fmt.Errorf("flag needs an argument: --%s", long)
		}
		assignString(f, long, value)
	case "int":
		if !hasValue {
			return fmt.Errorf("flag needs an argument: --%s", long)
		}
		n, err := strconv.Atoi(value)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag", value, "--"+long)
		}
		assignInt(f, long, n)
	case "strings":
		if !hasValue {
			return fmt.Errorf("flag needs an argument: --%s", long)
		}
		parts := splitCSV(value)
		assignStrings(f, long, parts)
	}
	return nil
}

func splitCSV(s string) []string {
	// simple CSV: split on comma, trim spaces
	parts := strings.Split(s, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		out = append(out, p)
	}
	return out
}

func assignBool(f *Flags, name string, v bool) {
	switch name {
	case "archive-browsing":
		f.ArchiveBrowsing = v
	case "collapse-path":
		f.CollapsePath = v
	case "enable-profiling":
		f.Profiling = v
	case "follow-symlinks":
		f.FollowSymlinks = v
	case "help":
		f.ShowHelp = v
	case "mouse":
		f.Mouse = v
	case "no-color":
		f.NoColor = v
	case "no-cross":
		f.NoCross = v
	case "no-delete":
		f.NoDelete = v
	case "no-hidden":
		f.NoHidden = v
	case "no-prefix":
		f.NoPrefix = v
	case "no-progress":
		f.NoProgress = v
	case "no-spawn-shell":
		f.NoSpawnShell = v
	case "no-unicode":
		f.NoUnicode = v
	case "non-interactive":
		f.NonInteractive = v
	case "read-from-storage":
		f.ReadFromStorage = v
	case "reverse-sort":
		f.ReverseSort = v
	case "sequential":
		f.SequentialScanning = v
	case "show-annexed-size":
		f.ShowAnnexedSize = v
	case "show-apparent-size":
		f.ShowApparentSize = v
	case "show-disks":
		f.ShowDisks = v
	case "show-in-kib":
		f.ShowInKiB = v
	case "show-item-count":
		f.ShowItemCount = v
	case "show-mtime":
		f.ShowMTime = v
	case "show-relative-size":
		f.ShowRelativeSize = v
	case "shared":
		// ignored for now
	case "si":
		f.UseSIPrefix = v
	case "summarize":
		f.Summarize = v
	case "use-git-ignore":
		f.UseGitIgnore = v
	case "version":
		f.ShowVersion = v
	case "write-config":
		f.WriteConfig = v
	}
}

func assignString(f *Flags, name string, v string) {
	switch name {
	case "config-file":
		f.CfgFile = v
	case "db":
		f.DbPath = v
	case "ignore-from":
		f.IgnoreFromFile = v
	case "input-file":
		f.InputFile = v
	case "log-file":
		f.LogFile = v
	case "max-age":
		f.MaxAge = v
	case "min-age":
		f.MinAge = v
	case "output-file":
		f.OutputFile = v
	case "since":
		f.Since = v
	case "storage":
		f.Storage = v
	case "style":
		f.Style = v
	case "until":
		f.Until = v
	}
}

func assignInt(f *Flags, name string, n int) {
	switch name {
	case "depth":
		f.Depth = n
	case "max-cores":
		f.MaxCores = n
	case "top":
		f.Top = n
	}
}

func assignStrings(f *Flags, name string, vals []string) {
	switch name {
	case "exclude-type":
		f.ExcludeTypeFilter = append(f.ExcludeTypeFilter, vals...)
	case "ignore-dirs":
		f.IgnoreDirs = vals
	case "ignore-dirs-pattern":
		f.IgnoreDirsPattern = append(f.IgnoreDirsPattern, vals...)
	case "type":
		f.TypeFilter = append(f.TypeFilter, vals...)
	}
}

// parseArgs parses argv according to Cobra/POSIX-like rules.
// Short flags can be combined (e.g., -nps) if they are bool-like.
// Short flags that take a value can have the value attached (-othis) or separate (-o this).
// Long flags take value either as --key=value or --key value.
func parseArgs(argv []string) (*Flags, error) {
	f := defaultFlags()

	i := 0
	for i < len(argv) {
		arg := argv[i]
		if arg == "--" {
			f.Args = append(f.Args, argv[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			rest := arg[2:]
			var name, value string
			hasValue := false
			if eq := strings.IndexByte(rest, '='); eq >= 0 {
				name = rest[:eq]
				value = rest[eq+1:]
				hasValue = true
			} else {
				name = rest
				def := findFlagByLong(name)
				if def == nil {
					return nil, fmt.Errorf("unknown flag: --%s", name)
				}
				if def.Has != "bool" {
					i++
					if i >= len(argv) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					value = argv[i]
					hasValue = true
				}
			}
			if err := setFlagValue(f, name, value, hasValue); err != nil {
				return nil, err
			}
			i++
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flag or cluster
			rest := arg[1:]
			j := 0
			for j < len(rest) {
				ch := string(rest[j])
				def := findFlagByShort(ch)
				if def == nil {
					return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", rest[j], rest)
				}
				if def.Has == "bool" {
					if err := setFlagValue(f, def.Long, "", false); err != nil {
						return nil, err
					}
					j++
				} else {
					// value is rest[j+1:] if non-empty, else next arg
					if j+1 < len(rest) {
						value := rest[j+1:]
						if err := setFlagValue(f, def.Long, value, true); err != nil {
							return nil, err
						}
						j = len(rest)
					} else {
						i++
						if i >= len(argv) {
							return nil, fmt.Errorf("flag needs an argument: -%s", ch)
						}
						if err := setFlagValue(f, def.Long, argv[i], true); err != nil {
							return nil, err
						}
						j = len(rest)
					}
				}
			}
			i++
		} else {
			f.Args = append(f.Args, arg)
			i++
		}
	}

	return f, nil
}
