				if def == nil {
					return nil, fmt.Errorf("unknown flag: --%s", name)
				}
				if def.Has != "bool" {
					i++
					if i >= len(argv) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					value = argv[i]
					hasValue = true
				}
			}
			if err := setFlagValue(f, name, value, hasValue); err != nil {
				return nil, err
			}
			i++
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flag or cluster
			rest := arg[1:]
			j := 0
			for j < len(rest) {
				ch := string(rest[j])
				def := findFlagByShort(ch)
				if def == nil {
					return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", rest[j], rest)
				}
				if def.Has == "bool" {
					if err := setFlagValue(f, def.Long, "", false); err != nil {
						return nil, err
					}
					j++
				} else {
					// value is rest[j+1:] if non-empty, else next arg
					if j+1 < len(rest) {
						value := rest[j+1:]
						if err := setFlagValue(f, def.Long, value, true); err != nil {
							return nil, err
						}
						j = len(rest)
					} else {
						i++
						if i >= len(argv) {
							return nil, fmt.Errorf("flag needs an argument: -%s", ch)
						}
						if err := setFlagValue(f, def.Long, argv[i], true); err != nil {
							return nil, err
						}
						j = len(rest)
					}
				}
			}
			i++
		} else {
			f.Args = append(f.Args, arg)
			i++
		}
	}

	return f, nil
