package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
)

// Item represents a scanned file or directory (or symlink).
type Item struct {
	Name     string
	Path     string // full path for roots, or just name for children
	IsDir    bool
	IsSymlink bool
	ASize    int64 // apparent size
	DSize    int64 // disk size
	MTime    int64
	Children []*Item
	Parent   *Item
	ReadError bool
	ChildReadError bool
	Empty    bool
}

func (it *Item) Size(flags *Flags) int64 {
	if flags.ShowApparentSize {
		return it.ASize
	}
	return it.DSize
}

// Flag character for display
func (it *Item) FlagChar() byte {
	if it.ReadError {
		return '!'
	}
	if it.ChildReadError {
		return '.'
	}
	if it.IsSymlink {
		return '@'
	}
	if it.IsDir && it.Empty {
		return 'e'
	}
	return ' '
}

// scanDir recursively scans a directory and returns the root Item.
// It respects flags for ignore, apparent size, etc.
func scanDir(root string, flags *Flags) (*Item, error) {
	info, err := os.Lstat(root)
	if err != nil {
		return nil, err
	}
	// Canonicalize path: absolute
	abs, err := filepath.Abs(root)
	if err != nil {
		abs = root
	}
	// Remove trailing slash unless root
	if len(abs) > 1 && strings.HasSuffix(abs, "/") {
		abs = strings.TrimRight(abs, "/")
	}
	if info.Mode()&os.ModeSymlink != 0 {
		// root is a symlink - treat as file
		it := &Item{
			Name:      filepath.Base(abs),
			Path:      abs,
			IsSymlink: true,
			ASize:     0,
			DSize:     0,
			MTime:     info.ModTime().Unix(),
		}
		return it, nil
	}
	if !info.IsDir() {
		asize := info.Size()
		dsize := blockSize(info)
		it := &Item{
			Name:  filepath.Base(abs),
			Path:  abs,
			ASize: asize,
			DSize: dsize,
			MTime: info.ModTime().Unix(),
		}
		return it, nil
	}
	rootItem := &Item{
		Name:  filepath.Base(abs),
		Path:  abs,
		IsDir: true,
		MTime: info.ModTime().Unix(),
	}
	// scan children
	scanChildren(rootItem, flags)
	return rootItem, nil
}

func scanChildren(dir *Item, flags *Flags) {
	entries, err := os.ReadDir(dir.Path)
	if err != nil {
		dir.ReadError = true
		return
	}
	// own size from dir stat
	if st, err := os.Lstat(dir.Path); err == nil {
		dir.ASize = st.Size()
		dir.DSize = blockSize(st)
	}
	for _, e := range entries {
		name := e.Name()
		full := filepath.Join(dir.Path, name)
		info, err := os.Lstat(full)
		if err != nil {
			continue
		}
		// hidden dir filter
		if flags.NoHidden && info.IsDir() && strings.HasPrefix(name, ".") {
			continue
		}
		// ignore dirs
		if info.IsDir() && isIgnoredDir(full, flags) {
			continue
		}
		if isIgnoredDirByPattern(full, flags) {
			continue
		}
		// exclude type (applies to files)
		if !info.IsDir() {
			ext := strings.TrimPrefix(filepath.Ext(name), ".")
			if len(flags.ExcludeTypeFilter) > 0 {
				if contains(flags.ExcludeTypeFilter, ext) {
					continue
				}
			}
			if len(flags.TypeFilter) > 0 {
				if !contains(flags.TypeFilter, ext) {
					continue
				}
			}
		}
		child := &Item{
			Name:   name,
			Path:   full,
			MTime:  info.ModTime().Unix(),
			Parent: dir,
		}
		if info.Mode()&os.ModeSymlink != 0 {
			child.IsSymlink = true
			if flags.FollowSymlinks {
				// follow for files only
				target, err := os.Stat(full)
				if err == nil && !target.IsDir() {
					child.ASize = target.Size()
					child.DSize = blockSize(target)
				}
			}
			dir.Children = append(dir.Children, child)
			continue
		}
		if info.IsDir() {
			child.IsDir = true
			scanChildren(child, flags)
			if len(child.Children) == 0 {
				child.Empty = true
			}
			if child.ChildReadError || child.ReadError {
				dir.ChildReadError = true
			}
			// aggregate
			dir.ASize += child.ASize
			dir.DSize += child.DSize
		} else {
			asize := info.Size()
			dsize := blockSize(info)
			child.ASize = asize
			child.DSize = dsize
			dir.ASize += asize
			dir.DSize += dsize
		}
		dir.Children = append(dir.Children, child)
	}
}

func blockSize(info os.FileInfo) int64 {
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		// blocks is number of 512-byte blocks
		return st.Blocks * 512
	}
	return info.Size()
}

func contains(ss []string, v string) bool {
	for _, s := range ss {
		if s == v {
			return true
		}
	}
	return false
}

func isIgnoredDir(full string, flags *Flags) bool {
	for _, p := range flags.IgnoreDirs {
		if full == p {
			return true
		}
	}
	return false
}

func isIgnoredDirByPattern(full string, flags *Flags) bool {
	// patterns are simple globs - we handle exact match and basic wildcards
	for _, p := range flags.IgnoreDirsPattern {
		matched, err := filepath.Match(p, filepath.Base(full))
		if err == nil && matched {
			return true
		}
	}
	return false
}

// sortChildren sorts children according to flags.
// Default: by Size desc, then by name desc (reverse alpha).
// With reverse-sort: by Size asc, then by name asc.
func sortChildren(it *Item, flags *Flags) {
	if !it.IsDir || len(it.Children) == 0 {
		return
	}
	children := it.Children
	sort.SliceStable(children, func(i, j int) bool {
		a, b := children[i], children[j]
		asz, bsz := a.Size(flags), b.Size(flags)
		if flags.ReverseSort {
			if asz != bsz {
				return asz < bsz
			}
			return a.Name < b.Name
		}
		if asz != bsz {
			return asz > bsz
		}
		return a.Name > b.Name
	})
}
