package main

import (
	"fmt"
	"io"
	"strings"
)

// printListing prints children of the root item using the default format.
// <flag-char><size padded to 10><space><name>
func printListing(w io.Writer, root *Item, flags *Flags) {
	sortChildren(root, flags)
	for _, c := range root.Children {
		size := c.Size(flags)
		ss := formatSize(size, flags)
		// right-align in width 10
		if len(ss) < 10 {
			ss = strings.Repeat(" ", 10-len(ss)) + ss
		}
		name := c.Name
		if c.IsDir {
			name = "/" + name
		}
		fmt.Fprintf(w, "%c%s %s\n", c.FlagChar(), ss, name)
	}
}

// printSummarize prints only the total line.
func printSummarize(w io.Writer, root *Item, flags *Flags) {
	size := root.Size(flags)
	ss := formatSize(size, flags)
	if len(ss) < 9 {
		ss = strings.Repeat(" ", 9-len(ss)) + ss
	}
	fmt.Fprintf(w, "%s %s\n", ss, root.Name)
}

// printDepth prints directory structure up to given depth.
// Uses path-based names and 9-width size field.
func printDepth(w io.Writer, root *Item, depth int, flags *Flags) {
	printDepthItem(w, root, root.Path, 0, depth, flags)
}

func printDepthItem(w io.Writer, it *Item, path string, level, maxDepth int, flags *Flags) {
	size := it.Size(flags)
	ss := formatSize(size, flags)
	if len(ss) < 9 {
		ss = strings.Repeat(" ", 9-len(ss)) + ss
	}
	fmt.Fprintf(w, "%s %s\n", ss, path)
	if !it.IsDir {
		return
	}
	if maxDepth > 0 && level >= maxDepth {
		// still print children as flat list? Actually in depth mode we continue always
		// Observation: --depth 1 and --depth 2 showed the same output with full recursion
		// That's weird. Let me emulate that.
	}
	sortChildren(it, flags)
	for _, c := range it.Children {
		childPath := path + "/" + c.Name
		printDepthItem(w, c, childPath, level+1, maxDepth, flags)
	}
}

// printFileLine prints a single file (when scan target is a file).
func printFileLine(w io.Writer, it *Item, flags *Flags) {
	size := it.Size(flags)
	ss := formatSize(size, flags)
	if len(ss) < 9 {
		ss = strings.Repeat(" ", 9-len(ss)) + ss
	}
	fmt.Fprintf(w, "%s %s\n", ss, it.Name)
}
