// isTerminal reports whether file descriptor fd refers to a terminal.
func isTerminal(f *os.File) bool {
	var termios [60]byte
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, f.Fd(), uintptr(getTCGETS()), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

func getTCGETS() uint {
	// Linux: 0x5401
	return 0x5401
}
