package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
)

// Item represents a scanned file or directory (or symlink).
type Item struct {
	Name           string
	Path           string
	IsDir          bool
	IsSymlink      bool
	ASize          int64
	DSize          int64
	MTime          int64
	Children       []*Item
	Parent         *Item
	ReadError      bool
	ChildReadError bool
	Empty          bool
}

func (it *Item) Size(flags *Flags) int64 {
	if flags.ShowApparentSize {
		return it.ASize
	}
	return it.DSize
}

// Flag character for display
func (it *Item) FlagChar() byte {
	if it.ReadError {
		return '!'
	}
	if it.ChildReadError {
		return '.'
	}
	if it.IsSymlink {
		return '@'
	}
	if it.IsDir && it.Empty {
		return 'e'
	}
	return ' '
}

// scanDir recursively scans a directory and returns the root Item.
func scanDir(root string, flags *Flags) (*Item, error) {
	info, err := os.Lstat(root)
	if err != nil {
		return nil, err
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		abs = root
	}
	if len(abs) > 1 && strings.HasSuffix(abs, "/") {
		abs = strings.TrimRight(abs, "/")
	}
	if info.Mode()&os.ModeSymlink != 0 {
		it := &Item{
			Name:      filepath.Base(abs),
			Path:      abs,
			IsSymlink: true,
			ASize:     0,
			DSize:     0,
			MTime:     info.ModTime().Unix(),
		}
		return it, nil
	}
	if !info.IsDir() {
		it := &Item{
			Name:  filepath.Base(abs),
			Path:  abs,
			ASize: info.Size(),
			DSize: diskSize(info),
			MTime: info.ModTime().Unix(),
		}
		return it, nil
	}
	rootItem := &Item{
		Name:  filepath.Base(abs),
		Path:  abs,
		IsDir: true,
		MTime: info.ModTime().Unix(),
		ASize: info.Size(),
		DSize: diskSize(info),
	}
	scanChildren(rootItem, flags)
	return rootItem, nil
}

func scanChildren(dir *Item, flags *Flags) {
	entries, err := os.ReadDir(dir.Path)
	if err != nil {
		dir.ReadError = true
		return
	}
	for _, e := range entries {
		name := e.Name()
		full := filepath.Join(dir.Path, name)
		info, err := os.Lstat(full)
		if err != nil {
			continue
		}
		// hidden dir filter
		if flags.NoHidden && info.IsDir() && strings.HasPrefix(name, ".") {
			continue
		}
		// ignore dirs
		if info.IsDir() && isIgnoredDir(full, flags) {
			continue
		}
		if isIgnoredDirByPattern(full, flags) {
			continue
		}
		// exclude/include type (applies to files)
		if !info.IsDir() {
			ext := strings.TrimPrefix(filepath.Ext(name), ".")
			if len(flags.ExcludeTypeFilter) > 0 && contains(flags.ExcludeTypeFilter, ext) {
				continue
			}
			if len(flags.TypeFilter) > 0 && !contains(flags.TypeFilter, ext) {
				continue
			}
		}
		child := &Item{
			Name:   name,
			Path:   full,
			MTime:  info.ModTime().Unix(),
			Parent: dir,
		}
		if info.Mode()&os.ModeSymlink != 0 {
			child.IsSymlink = true
			if flags.FollowSymlinks {
				target, err := os.Stat(full)
				if err == nil && !target.IsDir() {
					child.ASize = target.Size()
					child.DSize = diskSize(target)
					dir.ASize += child.ASize
					dir.DSize += child.DSize
				}
			}
			dir.Children = append(dir.Children, child)
			continue
		}
		if info.IsDir() {
			child.IsDir = true
			child.ASize = info.Size()
			child.DSize = diskSize(info)
			scanChildren(child, flags)
			if len(child.Children) == 0 {
				child.Empty = true
			}
			if child.ChildReadError || child.ReadError {
				dir.ChildReadError = true
			}
