	Name           string
	Path           string
	IsDir          bool
	IsSymlink      bool
	ASize          int64
	DSize          int64
	MTime          int64
	Children       []*Item
	Parent         *Item
	ReadError      bool
	ChildReadError bool
	Empty          bool
