func scanDir(root string, flags *Flags) (*Item, error) {
	info, err := os.Lstat(root)
	if err != nil {
		return nil, err
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		abs = root
	}
	if len(abs) > 1 && strings.HasSuffix(abs, "/") {
		abs = strings.TrimRight(abs, "/")
	}
	if info.Mode()&os.ModeSymlink != 0 {
		it := &Item{
			Name:      filepath.Base(abs),
			Path:      abs,
			IsSymlink: true,
			MTime:     info.ModTime().Unix(),
		}
		return it, nil
	}
	if !info.IsDir() {
		it := &Item{
			Name:  filepath.Base(abs),
			Path:  abs,
			ASize: info.Size(),
			DSize: diskSize(info),
			MTime: info.ModTime().Unix(),
		}
		return it, nil
	}
	rootItem := &Item{
		Name:  filepath.Base(abs),
		Path:  abs,
		IsDir: true,
		MTime: info.ModTime().Unix(),
		// For dirs, asize == dsize == block-rounded own size
		ASize: diskSize(info),
		DSize: diskSize(info),
	}
