		ASize: diskSize(info),
		DSize: diskSize(info),
	}
	scanChildren(rootItem, flags)
	return rootItem, nil
}

func scanChildren(dir *Item, flags *Flags) {
	entries, err := os.ReadDir(dir.Path)
	if err != nil {
		dir.ReadError = true
		return
	}
	for _, e := range entries {
		name := e.Name()
		full := filepath.Join(dir.Path, name)
		info, err := os.Lstat(full)
		if err != nil {
			continue
		}
		// hidden dir filter
		if flags.NoHidden && info.IsDir() && strings.HasPrefix(name, ".") {
			continue
		}
		// ignore dirs
		if info.IsDir() && isIgnoredDir(full, flags) {
			continue
		}
		if isIgnoredDirByPattern(full, flags) {
			continue
		}
		// exclude/include type (applies to files)
		if !info.IsDir() {
			ext := strings.TrimPrefix(filepath.Ext(name), ".")
			if len(flags.ExcludeTypeFilter) > 0 && contains(flags.ExcludeTypeFilter, ext) {
				continue
			}
			if len(flags.TypeFilter) > 0 && !contains(flags.TypeFilter, ext) {
				continue
			}
		}
		child := &Item{
			Name:   name,
			Path:   full,
			MTime:  info.ModTime().Unix(),
			Parent: dir,
		}
		if info.Mode()&os.ModeSymlink != 0 {
			child.IsSymlink = true
			if flags.FollowSymlinks {
				target, err := os.Stat(full)
				if err == nil && !target.IsDir() {
					child.ASize = target.Size()
					child.DSize = diskSize(target)
					dir.ASize += child.ASize
					dir.DSize += child.DSize
				}
			}
			dir.Children = append(dir.Children, child)
			continue
		}
		if info.IsDir() {
			child.IsDir = true
			// For dirs: asize == dsize == block-rounded
			ds := diskSize(info)
			child.ASize = ds
			child.DSize = ds
			scanChildren(child, flags)
			if len(child.Children) == 0 {
				child.Empty = true
			}
			if child.ChildReadError || child.ReadError {
				dir.ChildReadError = true
			}
			dir.ASize += child.ASize
			dir.DSize += child.DSize
		} else {
			child.ASize = info.Size()
			child.DSize = diskSize(info)
			dir.ASize += child.ASize
			dir.DSize += child.DSize
		}
		dir.Children = append(dir.Children, child)
	}
}

// diskSize estimates the disk usage of a file/dir.
// Uses max(stat.Blocks*512, ceil(size, blockSize)).
func diskSize(info os.FileInfo) int64 {
	var blocks int64
	var blksize int64 = 4096
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		blocks = st.Blocks
		if st.Blksize > 0 {
			blksize = int64(st.Blksize)
		}
	}
	fromBlocks := blocks * 512
	size := info.Size()
	fromSize := ((size + blksize - 1) / blksize) * blksize
	if fromBlocks > fromSize {
		return fromBlocks
	}
	return fromSize
}

func contains(ss []string, v string) bool {
	for _, s := range ss {
		if s == v {
			return true
		}
	}
	return false
}

func isIgnoredDir(full string, flags *Flags) bool {
	abs, err := filepath.Abs(full)
	if err != nil {
		abs = full
	}
	for _, p := range flags.IgnoreDirs {
		if p == "" {
			continue
		}
		pa, err := filepath.Abs(p)
		if err != nil {
			pa = p
		}
		if full == p || abs == pa {
			return true
		}
	}
	return false
}

func isIgnoredDirByPattern(full string, flags *Flags) bool {
	for _, p := range flags.IgnoreDirsPattern {
		matched, err := filepath.Match(p, filepath.Base(full))
		if err == nil && matched {
			return true
		}
	}
	return false
}

// sortChildren sorts children by (size DESC, name DESC) by default.
func sortChildren(it *Item, flags *Flags) {
	if !it.IsDir || len(it.Children) == 0 {
		return
	}
	children := it.Children
	sort.SliceStable(children, func(i, j int) bool {
		a, b := children[i], children[j]
		asz, bsz := a.Size(flags), b.Size(flags)
		if flags.ReverseSort {
			if asz != bsz {
				return asz < bsz
			}
			return a.Name < b.Name
		}
		if asz != bsz {
			return asz > bsz
		}
		return a.Name > b.Name
	})
}
